/**
 * Deployment-stable identifier. This value is generated by Vercel for every
 * production deployment. It is not a secret; do not use as authentication.
 */
export function productionVersion(): string {
 return process.env.VERCEL_GIT_COMMIT_SHA
  || process.env.VERCEL_URL
  || process.env.NEXT_PUBLIC_DAYBRIDGE_VERSION
  || 'development';
}
